// Golden master of the Orders HTTP API. Pricing (downstream) is an in-process fake.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 33.33, C: 60 }
const pricing = { async priceOf(sku) { return prices[sku] } }
let server, base

before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = (body, raw) => fetch(`${base}/orders`, { method: 'POST', body: raw ?? JSON.stringify(body) })
const json = async (res) => [res.status, res.headers.get('content-type'), await res.json()]

test('POST /orders creates an order: 201, json, id/items/total', async () => {
  const items = [{ sku: 'A', qty: 2 }]
  const [status, type, body] = await json(await post({ items }))
  assert.equal(status, 201)
  assert.equal(type, 'application/json')
  assert.match(body.id, /^\d+$/)
  assert.deepEqual(body.items, items)
  assert.equal(body.total, 20)
})

test('POST /orders ids are sequential strings', async () => {
  const a = (await json(await post({ items: [{ sku: 'A', qty: 1 }] })))[2]
  const b = (await json(await post({ items: [{ sku: 'A', qty: 1 }] })))[2]
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('POST /orders total of exactly 100 gets no discount', async () => {
  const [, , body] = await json(await post({ items: [{ sku: 'A', qty: 10 }] }))
  assert.equal(body.total, 100)
})

test('POST /orders total above 100 gets 10% discount', async () => {
  const [, , body] = await json(await post({ items: [{ sku: 'A', qty: 11 }] }))
  assert.equal(body.total, 99)
})

test('POST /orders sums several lines, then discount, then floors', async () => {
  const [, , body] = await json(await post({ items: [{ sku: 'C', qty: 2 }, { sku: 'A', qty: 1 }] }))
  assert.equal(body.total, 117 > 100 ? 117 - 11.7 | 0 : 0) // 105.3 floored
})

test('POST /orders floors fractional totals (truncates, not rounds)', async () => {
  const [, , body] = await json(await post({ items: [{ sku: 'B', qty: 3 }] }))
  assert.equal(body.total, 99) // 99.99
})

