  assert.equal(body.total, 100)
})

test('POST /orders total above 100 gets 10% discount', async () => {
  const [, , body] = await json(await post({ items: [{ sku: 'A', qty: 11 }] }))
  assert.equal(body.total, 99)
})

test('POST /orders sums several lines, then discount, then floors', async () => {
  const [, , body] = await json(await post({ items: [{ sku: 'C', qty: 2 }, { sku: 'A', qty: 1 }] }))
  assert.equal(body.total, 117 > 100 ? 117 - 11.7 | 0 : 0) // 105.3 floored
})

test('POST /orders floors fractional totals (truncates, not rounds)', async () => {
  const [, , body] = await json(await post({ items: [{ sku: 'B', qty: 3 }] }))
  assert.equal(body.total, 99) // 99.99
})

test('POST /orders non-numeric qty yields total null in JSON', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — no qty validation; NaN serialises to null
  const [status, , body] = await json(await post({ items: [{ sku: 'A', qty: 'x' }] }))
  assert.equal(status, 201)
  assert.equal(body.total, null)
})

test('POST /orders unknown sku yields total null in JSON', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — unpriced sku gives undefined*qty = NaN
  const [status, , body] = await json(await post({ items: [{ sku: 'ZZZ', qty: 1 }] }))
  assert.equal(status, 201)
  assert.equal(body.total, null)
})

for (const [name, body, raw] of [
  ['missing items', {}],
  ['empty body', undefined, ''],
  ['empty items', { items: [] }],
  ['items not an array', { items: 'A' }],
  ['invalid JSON', undefined, '{nope'],
]) {
  test(`POST /orders 400 for ${name}`, async () => {
    const [status, type, out] = await json(await post(body, raw))
    assert.equal(status, 400)
    assert.equal(type, 'application/json')
    assert.deepEqual(out, { error: 'items required' })
  })
}

test('GET /orders/:id returns the stored order', async () => {
  const created = (await json(await post({ items: [{ sku: 'A', qty: 3 }] })))[2]
  const [status, type, body] = await json(await fetch(`${base}/orders/${created.id}`))
  assert.equal(status, 200)
  assert.equal(type, 'application/json')
  assert.deepEqual(body, created)
})

test('GET /orders/:id for unknown id is 200 with error body', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — "not found" is returned with status 200, not 404
  const [status, , body] = await json(await fetch(`${base}/orders/does-not-exist`))
  assert.equal(status, 200)
  assert.deepEqual(body, { error: 'not found' })
})

for (const [method, path] of [['GET', '/orders'], ['GET', '/nope'], ['PUT', '/orders/1'], ['DELETE', '/orders/1'], ['GET', '/orders/1/extra'], ['POST', '/orders/1']]) {
  test(`${method} ${path} is 404 no route`, async () => {
    const [status, type, body] = await json(await fetch(base + path, { method }))
    assert.equal(status, 404)
    assert.equal(type, 'application/json')
    assert.deepEqual(body, { error: 'no route' })
  })
}
